To securely encrypt the user's ID and personal information before storing it in the cookie, you can use a cryptographic library such as `crypto/aes` to encrypt the cookie value before setting it:
```go
package main
import (
    "crypto/aes"
    "crypto/cipher"
    "crypto/rand"
    "encoding/base64"
    "fmt"
    "github.com/google/uuid"
    "io"
    "net/http"
)
// Key used to encrypt the cookie value
var key = []byte("supersecretkey")
func main() {
    http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
        // Check if the user already has a cookie
        cookie, err := r.Cookie("user_info")
        if err == http.ErrNoCookie {
            // If the user doesn't have a cookie, generate a new UUID
            id := uuid.New()
            // Encrypt the UUID, name, and email using AES
            plaintext := []byte(fmt.Sprintf("%s|%s|%s", id.String(), "John Doe", "john.doe@example.com"))
            ciphertext, err := encrypt(plaintext, key)
            if err != nil {
                http.Error(w, err.Error(), http.StatusInternalServerError)
                return
            }
            // Store the encrypted value in a cookie
            cookie = &http.Cookie{
                Name:  "user_info",
                Value: base64.URLEncoding.EncodeToString(ciphertext),
                Path:  "/",
            }
            http.SetCookie(w, cookie)
        } else {
            // If the user has a cookie, decrypt the value and display the user's information
            ciphertext, err := base64.URLEncoding.DecodeString(cookie.Value)
            if err != nil {
                http.Error(w, err.Error(), http.StatusBadRequest)
                return
            }
            plaintext, err := decrypt(ciphertext, key)
            if err != nil {
                http.Error(w, err.Error(), http.StatusInternalServerError)
                return
            }
            values := bytes.Split(plaintext, []byte("|"))
            fmt.Fprintf(w, "Your user ID is: %s\n", values[0])
            fmt.Fprintf(w, "Your name is: %s\n", values[1])
            fmt.Fprintf(w, "Your email address is: %s\n", values[2])
        }
    })
    http.ListenAndServe(":8080", nil)
}
// Encrypt plaintext using AES with the given key
func encrypt(plaintext, key []byte) ([]byte, error) {
    block, err := aes.NewCipher(key)
    if err != nil {
        return nil, err
    }
    ciphertext := make([]byte, aes.BlockSize+len(plaintext))
    iv := ciphertext[:aes.BlockSize]
    if _, err := io.ReadFull(rand.Reader, iv); err != nil {
        return nil, err
    }
    stream := cipher.NewCFBEncrypter(block, iv)
    stream.XORKeyStream(ciphertext[aes.BlockSize:], plaintext)
    return ciphertext, nil
}
// Decrypt ciphertext using AES with the given key
func decrypt(ciphertext, key []byte) ([]byte, error) {
    block, err := aes.NewCipher(key)
    if err != nil {
        return nil, err
    }
    if len(ciphertext) < aes.BlockSize {
        return nil, fmt.Errorf("ciphertext too short")
    }
    iv := ciphertext[:aes.BlockSize]
    ciphertext = ciphertext[aes.BlockSize:]
    stream := cipher.NewCFBDecrypter(block, iv)
    stream.XORKeyStream(ciphertext, ciphertext)
    return ciphertext, nil
}
```
Note that this code is just an example and should not be used as-is in production. You should always use a secure key and encryption algorithm, and follow best practices for storing and handling sensitive user information.

