int[] streetNumbers = {20356, 20408, 20402, 20430, 20376};
// Split each street number into its block number and street number within the block
int[][] splitStreetNumbers = new int[streetNumbers.length][2];
for (int i = 0; i < streetNumbers.length; i++) {
    splitStreetNumbers[i][0] = streetNumbers[i] / 100;
    splitStreetNumbers[i][1] = streetNumbers[i] % 100;
