import java.util.*;
public class ThreeLargestIntegers {
    public static int[] findThreeLargestIntegers(int[] nums) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int num : nums) {
            pq.offer(num);
            if (pq.size() > 3) {
                pq.poll();
            }
        }
        int[] result = new int[3];
        int i = 2;
        while (!pq.isEmpty()) {
            result[i--] = pq.poll();
        }
        return result;
