Sure, here are examples of each of the 4 fundamentals of Object Oriented Programming using C++ code:
1. Abstraction:
```
class Shape {
public:
    virtual float area() = 0;
    virtual float perimeter() = 0;
};
class Circle : public Shape {
private:
    float radius;
public:
    Circle(float r) {
        radius = r;
    }
    float area() {
        return 3.14 * radius * radius;
    }
    float perimeter() {
        return 2 * 3.14 * radius;
    }
};
class Rectangle : public Shape {
private:
    float length;
    float width;
public:
    Rectangle(float l, float w) {
        length = l;
        width = w;
    }
    float area() {
        return length * width;
    }
    float perimeter() {
        return 2 * (length + width);
    }
};
```
In this example, the `Shape` class is an abstract class that defines the essential features of a shape, which are the `area()` and `perimeter()` methods. The `Circle` and `Rectangle` classes inherit from the `Shape` class and implement these methods in their own way, while ignoring the rest of the details that are not essential to their definition.
2. Encapsulation:
```
class BankAccount {
private:
    float balance;
public:
    void deposit(float amount) {
        balance += amount;
    }
    void withdraw(float amount) {
        balance -= amount;
    }
    float getBalance() {
        return balance;
    }
};
int main() {
    BankAccount account;
    account.deposit(1000);
    account.withdraw(500);
    float balance = account.getBalance();
    return 0;
}
```
In this example, the `balance` variable is hidden within the `BankAccount` class and can only be accessed through the `deposit()`, `withdraw()`, and `getBalance()` methods. This ensures that the balance can only be modified in a controlled way and prevents any unauthorized access to it.
3. Inheritance:
```
class Animal {
public:
    virtual void makeSound() = 0;
};
class Dog : public Animal {
public:
    void makeSound() {
        cout << "Woof!" << endl;
    }
};
class Cat : public Animal {
public:
    void makeSound() {
        cout << "Meow!" << endl;
    }
};
int main() {
    Animal* animal1 = new Dog();
    Animal* animal2 = new Cat();
    animal1->makeSound();
    animal2->makeSound();
    return 0;
}
```
In this example, the `Dog` and `Cat` classes inherit from the `Animal` class, which defines the `makeSound()` method. The `Dog` and `Cat` classes override this method to make their own unique sound. This allows us to treat `Dog` and `Cat` objects as `Animal` objects and call the `makeSound()` method on them, without having to worry about their specific implementation details.
4. Polymorphism:
```
class Shape {
public:
    virtual float area() = 0;
    virtual float perimeter() = 0;
};
class Circle : public Shape {
private:
    float radius;
public:
    Circle(float r) {
        radius = r;
    }
