Here is a sample C++ code that can read a CSV file containing carbon emission data and compute the yearly average emission:
```c++
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;
int main()
{
    string line;
    ifstream myfile ("carbon_emissions.csv");
    vector<double> emissions;
    double total_emission = 0;
    if (myfile.is_open())
    {
        while ( getline (myfile,line) )
        {
            stringstream ss(line);
            string token;
            // extract year and emission value
            getline(ss, token, ','); // year
            getline(ss, token, ','); // emission
            double emission = stod(token);
            emissions.push_back(emission);
        }
        myfile.close();
        // calculate average emission per year
        int num_years = emissions.size();
        double avg_emission = 0;
        for(int i=0; i<num_years; i++) {
            total_emission += emissions[i];
        }
        avg_emission = total_emission / num_years;
        cout << "Average carbon emission per year: " << avg_emission << endl;
    }
    return 0;
}
```
